          ["Orientação", "Último dia do ano: depois dos avisos e antes da bênção final, canta-se o hino Te Deum em ação de graças pelo ano que termina (costume da paróquia)."],
          ["Cantores e Todos", "Te Deum laudamus: te Dominum confitemur.\nTe aeternum Patrem omnis terra veneratur.\nTibi omnes Angeli; tibi caeli et universae Potestates;\nTibi Cherubim et Seraphim incessabili voce proclamant:\nSanctus, Sanctus, Sanctus, Dominus Deus Sabaoth.\nPleni sunt caeli et terra maiestatis gloriae tuae.\nTe gloriosus Apostolorum chorus,\nTe Prophetarum laudabilis numerus,\nTe Martyrum candidatus laudat exercitus.\nTe per orbem terrarum sancta confitetur Ecclesia, Patrem immensae maiestatis:\nVenerandum tuum verum et unicum Filium;\nSanctum quoque Paraclitum Spiritum.\nTu Rex gloriae, Christe.\nTu Patris sempiternus es Filius.\nTu ad liberandum suscepturus hominem,\nnon horruisti Virginis uterum.\nTu, devicto mortis aculeo,\naperuisti credentibus regna caelorum.\nTu ad dexteram Dei sedes, in gloria Patris.\nIudex crederis esse venturus.\nTe ergo quaesumus, tuis famulis subveni:\nquos pretioso sanguine redemisti.\nAeterna fac cum sanctis tuis in gloria numerari.\nSalvum fac populum tuum, Domine, et benedic hereditati tuae.\nEt rege eos, et extolle illos usque in aeternum.\nPer singulos dies benedicimus te;\nEt laudamus Nomen tuum in saeculum, et in saeculum saeculi.\nDignare, Domine, die isto sine peccato nos custodire.\nMiserere nostri Domine,\nmiserere nostri.\nFiat misericordia tua, Domine, super nos,\nquemadmodum speravimus in te.\nIn te, Domine, speravi: non confundar in aeternum."]
